from pathlib import Path
from html import escape
import json
root=Path(__file__).resolve().parents[1]
folder=root/'release'
items=[('Inicio','qa-623-inicio.png'),('Estudio','qa-623-estudio.png'),('Tareas y estadísticas','qa-623-tareas.png'),('Notas','qa-623-notas.png'),('Música','qa-623-musica.png'),('Planificador','qa-623-planificacion.png'),('Cursos','qa-623-cursos.png'),('Interior de un curso','qa-623-curso_detalle.png'),('IA · nuevo chat','qa-623-ia.png'),('Ajustes','qa-623-ajustes.png'),('Charvis · consulta y fuentes de prueba','qa-charvis-623-refined-research.png'),('Proyecto · archivos y materiales','qa-charvis-623-project-materials.png'),('Markdown','qa-charvis-623-markdown.png'),('Fórmulas y citas','qa-charvis-623-formulas-quote.png'),('Documento de Word','qa-charvis-623-docx.png'),('Hoja de Excel','qa-charvis-623-xlsx.png'),('Presentación','qa-charvis-623-pptx.png'),('PDF · lectura por páginas','qa-charvis-623-pdf.png'),('Dictado · captura simulada','qa-charvis-623-recording.png'),('Listas · portada personalizada','qa-music-623-playlist.png'),('Artistas · catálogo de prueba','qa-music-623-artist.png'),('Sesión de estudio','qa-course-623-session-preview.png')]
sections=[]
for title,name in items:
 if (folder/name).exists():sections.append(f'<section><h2>{escape(title)}</h2><a href="{escape(name)}" target="_blank"><img loading="lazy" src="{escape(name)}" alt="{escape(title)}"></a></section>')
report=json.loads((folder/'qa-623-idle-performance.json').read_text(encoding='utf-8'))['report'] if (folder/'qa-623-idle-performance.json').exists() else []
rows=''.join(f'<tr><td>{escape(item["view"])}</td><td>{item["rendererTaskMs"]} ms</td><td>{item["scriptMs"]} ms</td><td>{item["heapMiB"]} MiB</td></tr>' for item in report)
html='''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>APHEKA 6.23 · Revisión visual</title><style>*{box-sizing:border-box}body{margin:0;background:#101112;color:#ebece9;font:15px/1.6 system-ui,sans-serif}main{max-width:1500px;margin:auto;padding:38px 28px}header{margin-bottom:30px;border-bottom:1px solid #343638;padding-bottom:25px}h1{font-size:30px;font-weight:550;letter-spacing:-.04em;margin:5px 0}p{max-width:850px;color:#b1b6b4}small{color:#91aa9f}h2{font-size:16px;font-weight:500;margin:0 0 12px}article{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:28px 22px}section{min-width:0}img{display:block;width:100%;height:auto;border:1px solid #343638;border-radius:7px}table{border-collapse:collapse;width:min(100%,750px);font-size:13px;margin:20px 0 40px}th,td{padding:9px 13px;border-bottom:1px solid #343638;text-align:left}th{color:#a3bdb2;font-weight:500}a{color:#b6cdc3}@media(max-width:800px){article{grid-template-columns:1fr}main{padding:24px 16px}h1{font-size:25px}}</style><main><header><small>APHEKA · 6.23.0 · 31 OCT 2026</small><h1>Revisión de interfaz y funcionamiento</h1><p>Capturas con datos de prueba aislados. Las consultas, el catálogo y la transcripción mostrados usan respuestas controladas; no representan acceso a tu biblioteca, a una cuenta de IA ni a tus materiales personales.</p><p>Frontend compilado y pruebas verificadas. Instalador 6.23 compilado y verificado.</p></header><h2>Tiempo del navegador en reposo</h2><p>Muestras de 2,2 segundos con 150 tareas y 250 sesiones. Son mediciones del proceso de renderizado en Edge, no de consumo eléctrico ni temperatura de la laptop.</p><table><thead><tr><th>Apartado</th><th>Trabajo total</th><th>JavaScript</th><th>Memoria JS</th></tr></thead><tbody>'''+rows+'</tbody></table><article>'+''.join(sections)+'</article></main></html>'
(folder/'qa-623-gallery.html').write_text(html,encoding='utf-8')
print(f'Galería creada: {len(sections)} capturas')
